# ---------------------------------------------------------------------------
# exact helpers -- no float and no tolerance anywhere
# ---------------------------------------------------------------------------
def nonzero_entries(matrix: sp.MatrixBase) -> int:
    return sum(1 for i in range(matrix.rows) for j in range(matrix.cols)
               if matrix[i, j] != 0)


def residual_count(matrix: sp.MatrixBase) -> int:
    """THE RESIDUAL, COUNTED: exact nonzero entries after exact expansion.  A
    count of 0 is the exact zero-matrix statement and no tolerance is involved
    at any point."""
    return nonzero_entries(sp.expand(matrix))


# ---------------------------------------------------------------------------
# the cover: the shift cocycle, the chart differentials, the section
# ---------------------------------------------------------------------------
T_COVER, X_EXTENT = b128.COVER_TIME_EXTENT, b128.SPACE_EXTENT
PHYSICAL_T = b128.PHYSICAL_TIME_EXTENT
N_COVER = T_COVER * X_EXTENT
MASS = b128.MASS
IU = sp.I
SYMBOLIC_MASS = sp.Symbol("m", positive=True)


def cover_shift(dt: int, dx: int) -> sp.Matrix:
    """The PLAIN translation on the cover: no staggered sign is needed."""
    shift = sp.zeros(N_COVER, N_COVER)
    for t in range(T_COVER):
        for x in range(X_EXTENT):
            shift[b128.cover_index(t + dt, x + dx), b128.cover_index(t, x)] = 1
    return shift


def completion(hodge: sp.Matrix, differential: sp.Matrix,
               mass: object = MASS) -> sp.Matrix:
    """The LANDED b128 completion convention, applied to a supplied pairing.
    `mass` defaults to the LANDED MASS = 2/7 and is passed as the SYMBOLIC
    positive mass for the same-action pullback leg."""
    return sp.expand(mass * hodge
                     + IU * (hodge * differential + differential.H * hodge))


def quotient_shift(dim: int, time_extent: int, dt: int, dx: int,
                   wrap: int, space_wrap: int = 1) -> sp.Matrix:
    """The induced shift on the antiperiodic quotient.

    `wrap` is the sign picked up crossing the TEMPORAL seam: -1 is the
    ANTIPERIODIC wrap and +1 is the periodic control.  `space_wrap` is the
    sign picked up crossing the SPATIAL seam -- +1 is the physical (periodic)
    convention, and -1 exists ONLY as a wrap-uniqueness control.
    """
    shift = sp.zeros(dim, dim)
    for t in range(time_extent):
        for x in range(X_EXTENT):
            t2 = t + dt
            x2 = x + dx
            sign = wrap if (t2 >= time_extent or t2 < 0) else 1
            sign *= space_wrap if (x2 >= X_EXTENT or x2 < 0) else 1
            shift[(t2 % time_extent) * X_EXTENT + x2 % X_EXTENT,
                  t * X_EXTENT + x] = sign
    return shift


def exterior_grade(time_extent: int) -> sp.Matrix:
    """BLOCK 106's OWN EXTERIOR DEGREE, deg = t%2 + x%2, laid on the b128 site
    order.  At time extent 4 this IS Block 106's `N_glob` as a matrix, which
    gate E verifies rather than assumes."""
    return sp.diag(*[sp.Integer((t % 2) + (x % 2))
                     for t in range(time_extent) for x in range(X_EXTENT)])


def sign_field(time_extent: int) -> sp.Matrix:
    """sgn_x = diag((-1)^x), the offset part of Block 106's Lambda_t sign field
    (its eq 30) written on the b128 site order."""
    return sp.diag(*[sp.Integer(-1) ** x
                     for _ in range(time_extent) for x in range(X_EXTENT)])


def hodge_cover(field: dict) -> sp.Matrix:
    """THE PARAMETERIZED COVER HODGE H[g].  The LANDED b128 curved_hodge_cover
    construction with the field left free: the anchor blocks are the LANDED
    Block 105 shear Hodge, the field has period 4 in t and is lifted to the
    8-cover, and gate G controls H[landed field] against the landed object."""
    result = sp.zeros(N_COVER, N_COVER)
    for t in range(T_COVER):
        for x in range(X_EXTENT):
            shear, volume = field[(t % PHYSICAL_T, x)]
            embedding = b128.cover_embedding(t, x)
            result += (embedding
                       * b128.block105.shear_hodge(shear, volume)
                       * embedding.T / 4)
    return sp.expand(result)


def shifted_field(field: dict, dt: int, dx: int) -> dict:
    """Block 106's ACTIVE field translation convention (T_a g)_(n+a) = g_n."""
    return {(t, x): field[((t - dt) % PHYSICAL_T, (x - dx) % X_EXTENT)]
            for t in range(PHYSICAL_T) for x in range(X_EXTENT)}


def flipped_field(field: dict) -> dict:
    """Block 106's shear flip F(q, v) = (-q, v), its eq 34."""
    return {site: (-shear, volume) for site, (shear, volume) in field.items()}


def note_text() -> tuple:
    """(text, at_final_path).  THE FINAL PATH IS THE ONLY PATH READ: there is no
    draft fallback anywhere in this runner, so before landing the text is empty
    and gate H fails on note-at-final-path alone."""
    try:
        return NOTE_PATH.read_text(encoding="utf-8"), True
    except OSError:
        return "", False


def landed_text(path: str) -> str:
    """A LANDED PRIMARY BODY, read at its own path in the worktree.  Gate C
    reads the Block 106 and Block 181 notes through this and through nothing
    else -- the process fix this block adopts is that every citation is checked
    against the primary body, never against a summary of it."""
    try:
        return (ROOT / path).read_text(encoding="utf-8")
    except OSError:
        return ""


