def build_claims(mutation: str) -> dict:
    claims: dict = {
        # A -- the authority pins.
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        # B -- the banner's declared status flags.
        "objects_registered": False,
        "ward_contraction_claimed": WARD_CONTRACTION_CLAIMED,
        "gravity_claimed": GRAVITY_CLAIMED,
        "complex_gauge_equivalence_claimed": COMPLEX_GAUGE_EQUIVALENCE_CLAIMED,
        # C -- the corpus-correction pins, read from the LANDED primary bodies.
        "b106_executed_pin": True,
        "b106_reachability_pin": True,
        "b106_no_ward_pin": True,
        "b181_stale_pin": True,
        "correction_edits_a_landed_note": CORRECTION_EDITS_A_LANDED_NOTE,
        # D -- the isometry package.
        "isometry_residual": ZERO_RESIDUAL,
        "patch_dim": PATCH_DIM,
        "range_invariance_residual": ZERO_RESIDUAL,
        "hodge_pullback_residual": ZERO_RESIDUAL,
        "action_pullback_residual": ZERO_RESIDUAL,
        "mass_is_symbolic": True,
        # E -- the grading.
        "cover_grading_residual": ZERO_RESIDUAL,
        "quotient_grading_residual": ZERO_RESIDUAL,
        "quotient_grade_is_b106_verbatim": True,
        "canonical_defect_rank": CANONICAL_GRADE_DEFECT_RANK,
        "transported_defect_rank": 0,
        "grade_intertwiner_residual": ZERO_RESIDUAL,
        # F -- the signed lifts and the symmetry.
        "anticommutator_residual": ZERO_RESIDUAL,
        "square_residual": ZERO_RESIDUAL,
        "squares_are_not_identity": True,
        "two_step_flat_residual": ZERO_RESIDUAL,
        "one_step_commutator_rank": ONE_STEP_COMMUTATOR_RANK,
        "signed_conjugate_nilpotency_residual": ZERO_RESIDUAL,
        "signed_conjugate_rank": SIGNED_CONJUGATE_RANK,
        "signed_conjugate_identity_residual": ZERO_RESIDUAL,
        "signed_conjugate_is_d10": False,
        "signed_conjugate_is_graded": False,
        # G -- the shear-flip package and the R-versus-NS dividend.
        "hodge_control_residual": ZERO_RESIDUAL,
        "plain_covariance_residual": ZERO_RESIDUAL,
        "flip_residual": ZERO_RESIDUAL,
        "unflipped_residual_rank": UNFLIPPED_RESIDUAL_RANK,
        "flipped_residual_rank": FLIPPED_RESIDUAL_RANK,
        "quotient_descent_residual": ZERO_RESIDUAL,
        "two_step_curved_residual": ZERO_RESIDUAL,
        "fine_periodic_rank": FINE_PERIODIC_RANK,
        "quotient_antiperiodic_rank": QUOTIENT_ANTIPERIODIC_RANK,
        "complex_difference_entries": COMPLEX_DIFFERENCE_ENTRIES,
        "complex_seam_entries": COMPLEX_SEAM_ENTRIES,
        "quotient_is_seam_negation": False,
        # H -- the note and the fence.
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_objects_registered":
        # THE BANNER DENIED: the imposed objects asserted REGISTERED, which
        # zero registered and zero adopted objects forbid.
        claims["objects_registered"] = True
    elif mutation == "claim_ward_contraction_theorem":
        # BLOCK 106's OWN DISCLAIMER DENIED: the same-action pullback asserted
        # to be a Ward-contraction (hence OS) theorem for the patch carrier,
        # which the pullback identity alone never supplies and which Block 106
        # explicitly refused for exactly this construction.
        claims["ward_contraction_claimed"] = True
    elif mutation == "claim_complex_gauge_equivalence":
        # THE COMPARISON OVERSOLD: the Block 106 fine complex and the Block 181
        # quotient complex asserted GAUGE-EQUIVALENT on the shared 16-dimensional
        # carrier, which the measured rank 6 against rank 8 forbids outright.
        claims["complex_gauge_equivalence_claimed"] = True
    elif mutation == "break_correction_pins":
        # THE CORRECTION UNGROUNDED: Block 106's own execution pin asserted
        # ABSENT from its primary body -- which is exactly the reading that
        # made the Block 181 citation wrong, and the measured presence of the
        # sentence forbids it.
        claims["b106_executed_pin"] = False
    elif mutation == "break_isometry":
        # THE ISOMETRY BROKEN: a NONZERO A^T A - I residual asserted allowed,
        # which the exact four-fold cover identity forbids.
        claims["isometry_residual"] = 4
    elif mutation == "break_pullback":
        # THE SAME-ACTION PULLBACK BROKEN: a nonzero A^T Q_patch A - Q_s
        # residual asserted allowed, which the exact eq-26 identity at symbolic
        # mass forbids.
        claims["action_pullback_residual"] = 4
    elif mutation == "break_canonical_defect_48":
        # THE W1 ANALOGUE ERASED: the canonical untransported patch grade
        # asserted compatible, which the measured rank-48 defect forbids.
        claims["canonical_defect_rank"] = 0
    elif mutation == "break_transported_defect":
        # THE CO-TRANSPORT LESSON DENIED: the transported grade asserted to
        # carry Block 106's rank-12 defect, which the measured exact zero
        # forbids.
        claims["transported_defect_rank"] = B106_CANONICAL_GRADE_DEFECT_RANK
    elif mutation == "break_projective_algebra":
        # THE PROJECTIVE ALGEBRA BROKEN: a nonzero anticommutator residual
        # asserted allowed, which the exact anticommutation forbids.
        claims["anticommutator_residual"] = 4
    elif mutation == "break_one_step_rank_24":
        # THE CHART MOVE HIDDEN: the plain ONE-STEP time shift asserted to be a
        # symmetry of the flat completion, which the measured rank-24
        # commutator forbids -- one-step shifts move the chart.
        claims["one_step_commutator_rank"] = 0
    elif mutation == "break_flip_identity":
        # THE SHEAR FLIP DELETED: a nonzero signed-t flip residual asserted
        # allowed, which the exact eq-34 identity forbids.
        claims["flip_residual"] = 4
    elif mutation == "break_rank6_rank8":
        # THE R-VERSUS-NS DIVIDEND ERASED: the PERIODIC fine differential
        # asserted to have the antiperiodic rank 8, which the measured rank 6
        # and its four harmonic modes forbid.
        claims["fine_periodic_rank"] = QUOTIENT_ANTIPERIODIC_RANK
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim")
    return claims


