@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    note_at_final_path: bool
    scope: dict
    banners: dict
    correction_pins: dict
    isometry_residual: int
    patch_dim: int
    range_invariance_residual: int
    hodge_pullback_residual: int
    action_pullback_residual: int
    mass_is_symbolic: bool
    cover_grading_residual: int
    quotient_grading_residual: int
    quotient_grade_is_b106_verbatim: bool
    canonical_defect_rank: int
    transported_defect_rank: int
    grade_intertwiner_residual: int
    anticommutator_residual: int
    square_residual: dict
    squares_are_not_identity: bool
    two_step_flat_residual: dict
    one_step_commutator_rank: int
    signed_conjugate_nilpotency_residual: int
    signed_conjugate_rank: int
    signed_conjugate_identity_residual: int
    signed_conjugate_is_d10: bool
    signed_conjugate_is_graded: bool
    hodge_control_residual: int
    plain_covariance_residual: dict
    flip_residual: int
    unflipped_residual_rank: int
    flipped_residual_rank: int
    quotient_descent_residual: dict
    two_step_curved_residual: dict
    fine_periodic_rank: int
    quotient_antiperiodic_rank: int
    harmonic_modes: int
    complex_difference_entries: int
    complex_seam_entries: int
    quotient_is_seam_negation: bool


def measure() -> Facts:
    text, at_final_path = note_text()
    main_head = resolve_ref("origin/main")

    Ut, Ux = cover_shift(1, 0), cover_shift(0, 1)
    SMAP = {
        (0, 0): sp.eye(N_COVER),
        (0, 1): Ux,
        (1, 0): Ut,
        (1, 1): sp.expand(Ut * Ux),
    }
    D = {o: sp.Matrix(b128.chart_differential_cover(o)) for o in ORIGINS}
    d00 = D[(0, 0)]
    H = sp.Matrix(b128.curved_hodge_cover())
    Hs = sp.expand(
        sum([SMAP[o].T * H * SMAP[o] for o in ORIGINS],
            sp.zeros(N_COVER, N_COVER)) / 4)

    # --- C: the corpus-correction pins, from the LANDED primary bodies ------
    b106_note = landed_text(BLOCK106_NOTE)
    b181_note = landed_text(BLOCK181_NOTE)
    correction_pins = {
        "b106_executed_pin": B106_EXECUTED_PIN in b106_note,
        "b106_reachability_pin": B106_REACHABILITY_PIN in b106_note,
        "b106_no_ward_pin": B106_NO_WARD_PIN in b106_note,
        "b181_stale_pin": B181_STALE_PIN in b181_note,
        "correction_edits_a_landed_note": CORRECTION_EDITS_A_LANDED_NOTE,
    }

    # --- D: the isometry package, T1 ---------------------------------------
    # A = s/2: the LANDED b181 graph section s(v) = (v, S_1 v, S_2 v, S_3 v)
    # halved.  D_patch, H_patch and Q_patch are the b106 patch objects rebuilt
    # on this carrier: the differential is the chart family, the Hodge is the
    # landed curved Hodge REPLICATED per patch.
    A = sp.Matrix.vstack(*[SMAP[o] * sp.Rational(1, 2) for o in ORIGINS])
    D_patch = sp.diag(*[D[o] for o in ORIGINS])
    H_patch = sp.diag(*[H for _ in ORIGINS])
    isometry_residual = residual_count(A.T * A - sp.eye(N_COVER))
    range_invariance_residual = residual_count(D_patch * A - A * d00)
    hodge_pullback_residual = residual_count(A.T * H_patch * A - Hs)
    Q_patch = completion(H_patch, D_patch, SYMBOLIC_MASS)
    Q_s_symbolic = completion(Hs, d00, SYMBOLIC_MASS)
    action_pullback_residual = residual_count(A.T * Q_patch * A - Q_s_symbolic)

    # --- E: the grading, T2 -------------------------------------------------
    N = exterior_grade(T_COVER)
    cover_grading_residual = residual_count(N * d00 - d00 * N - d00)
    DQ = {o: sp.Matrix(b128.antiperiodic_quotient(D[o])) for o in ORIGINS}
    n_quot = DQ[(0, 0)].shape[0]
    t_quot = n_quot // X_EXTENT
    N_q = exterior_grade(t_quot)
    quotient_grading_residual = residual_count(
        N_q * DQ[(0, 0)] - DQ[(0, 0)] * N_q - DQ[(0, 0)])
    # THE VERBATIM CHECK: the b106 exterior grade is READ from the LANDED b106
    # module, not re-derived, and compared entry for entry.
    b106_core = b106.core_objects(SYMBOLIC_MASS)
    b106_grade = sp.Matrix(b106_core["N_glob"])
    quotient_grade_is_b106_verbatim = bool(
        N_q.shape == b106_grade.shape
        and residual_count(N_q - b106_grade) == 0)
    N_canonical = sp.diag(*[N for _ in ORIGINS])
    canonical_defect_rank = sp.expand(
        N_canonical * D_patch - D_patch * N_canonical - D_patch).rank()
    N_transported = sp.diag(
        *[sp.expand(SMAP[o] * N * SMAP[o].T) for o in ORIGINS])
    transported_defect_rank = sp.expand(
        N_transported * D_patch - D_patch * N_transported - D_patch).rank()
    grade_intertwiner_residual = residual_count(N_transported * A - A * N)

    # --- F: the signed lifts and the symmetry, S3a / S5 / T3 ---------------
    sgn_x = sign_field(T_COVER)
    Ut_signed = sp.expand(sgn_x * Ut)
    Ux_signed = Ux
    anticommutator_residual = residual_count(
        Ut_signed * Ux_signed + Ux_signed * Ut_signed)
    square_residual = {
        "t": residual_count(Ut_signed * Ut_signed - Ut * Ut),
        "x": residual_count(Ux_signed * Ux_signed - Ux * Ux),
    }
    squares_are_not_identity = bool(
        residual_count(Ut * Ut - sp.eye(N_COVER)) != 0
        and residual_count(Ux * Ux - sp.eye(N_COVER)) != 0)
    Q_flat = completion(sp.eye(N_COVER), d00)
    two_step_flat_residual = {
        "t": residual_count(Ut * Ut * Q_flat - Q_flat * Ut * Ut),
        "x": residual_count(Ux * Ux * Q_flat - Q_flat * Ux * Ux),
    }
    one_step_commutator_rank = sp.expand(Ut * Q_flat - Q_flat * Ut).rank()
    signed_conjugate = sp.expand(Ut_signed * d00 * Ut_signed.T)
    signed_conjugate_nilpotency_residual = residual_count(
        signed_conjugate * signed_conjugate)
    signed_conjugate_rank = signed_conjugate.rank()
    signed_conjugate_identity_residual = residual_count(
        signed_conjugate - sgn_x * D[(1, 0)] * sgn_x)
    signed_conjugate_is_d10 = residual_count(signed_conjugate - D[(1, 0)]) == 0
    signed_conjugate_is_graded = residual_count(
        N * signed_conjugate - signed_conjugate * N - signed_conjugate) == 0

    # --- G: the ADM shear-flip package, S4 / T4 / S5-curved ----------------
    field = b128.block105.overlap_field()
    H_field = hodge_cover(field)
    hodge_control_residual = residual_count(H_field - H)
    plain_covariance_residual = {
        "x+": residual_count(
            Ux * H_field * Ux.T - hodge_cover(shifted_field(field, 0, 1))),
        "x-": residual_count(
            Ux.T * H_field * Ux - hodge_cover(shifted_field(field, 0, -1))),
        "t+": residual_count(
            Ut * H_field * Ut.T - hodge_cover(shifted_field(field, 1, 0))),
        "t-": residual_count(
            Ut.T * H_field * Ut - hodge_cover(shifted_field(field, -1, 0))),
    }
    signed_temporal_image = sp.expand(Ut_signed * H_field * Ut_signed.T)
    flipped_translate = hodge_cover(
        shifted_field(flipped_field(field), 1, 0))
    flip_residual = residual_count(signed_temporal_image - flipped_translate)
    unflipped_residual_rank = sp.expand(
        signed_temporal_image - hodge_cover(shifted_field(field, 1, 0))).rank()
    flipped_residual_rank = sp.expand(
        Ut * H_field * Ut.T - flipped_translate).rank()

    def quotient_hodge(source: dict) -> sp.Matrix:
        return sp.Matrix(b128.antiperiodic_quotient(hodge_cover(source)))

    Uxq = quotient_shift(n_quot, t_quot, 0, 1, 1)
    Utq_anti = quotient_shift(n_quot, t_quot, 1, 0, -1)
    Utq_signed = sp.expand(sign_field(t_quot) * Utq_anti)
    Hq_field = quotient_hodge(field)
    quotient_descent_residual = {
        "plain_x": residual_count(
            Uxq * Hq_field * Uxq.T - quotient_hodge(shifted_field(field, 0, 1))),
        "twisted_t_plain_field": residual_count(
            Utq_anti * Hq_field * Utq_anti.T
            - quotient_hodge(shifted_field(field, 1, 0))),
        "signed_twisted_t_flipped_field": residual_count(
            Utq_signed * Hq_field * Utq_signed.T
            - quotient_hodge(shifted_field(flipped_field(field), 1, 0))),
    }

    def section_completion(source: dict) -> sp.Matrix:
        raw = hodge_cover(source)
        averaged = sp.expand(
            sum([SMAP[o].T * raw * SMAP[o] for o in ORIGINS],
                sp.zeros(N_COVER, N_COVER)) / 4)
        return completion(averaged, d00)

    Ut2, Ux2 = sp.expand(Ut * Ut), sp.expand(Ux * Ux)
    Q_section = section_completion(field)
    two_step_curved_residual = {
        "t+": residual_count(
            Ut2 * Q_section * Ut2.T
            - section_completion(shifted_field(field, 2, 0))),
        "t-": residual_count(
            Ut2.T * Q_section * Ut2
            - section_completion(shifted_field(field, -2, 0))),
        "x+": residual_count(
            Ux2 * Q_section * Ux2.T
            - section_completion(shifted_field(field, 0, 2))),
        "x-": residual_count(
            Ux2.T * Q_section * Ux2
            - section_completion(shifted_field(field, 0, -2))),
    }

    # THE R-VERSUS-NS DIVIDEND: the LANDED b106 PERIODIC fine differential
    # against the LANDED b181 ANTIPERIODIC quotient differential, on the SAME
    # 16-dimensional carrier and in the SAME site order.
    d_fine = sp.Matrix(b106_core["d_glob"])
    d_quot = DQ[(0, 0)]
    fine_periodic_rank = d_fine.rank()
    quotient_antiperiodic_rank = d_quot.rank()
    harmonic_modes = d_fine.shape[0] - 2 * fine_periodic_rank
    difference = sp.expand(d_quot - d_fine)
    complex_difference_entries = nonzero_entries(difference)
    seam = tuple(
        (row, column)
        for row in range(difference.rows) for column in range(difference.cols)
        if difference[row, column] != 0
        and (row // X_EXTENT, column // X_EXTENT) in ((t_quot - 1, 0),
                                                      (0, t_quot - 1)))
    complex_seam_entries = len(seam)
    seam_negated = sp.Matrix(d_fine)
    for row in range(seam_negated.rows):
        for column in range(seam_negated.cols):
            if (row // X_EXTENT, column // X_EXTENT) in ((t_quot - 1, 0),
                                                         (0, t_quot - 1)):
                seam_negated[row, column] = -seam_negated[row, column]
    quotient_is_seam_negation = residual_count(d_quot - seam_negated) == 0

    banners = {
        "imposed_objects": len(IMPOSED_OBJECTS),
        "registered_objects": len(REGISTERED_OBJECTS),
        "adopted_objects": len(ADOPTED_OBJECTS),
        # THE DECLARED STATUS FLAGS, so the B mutations bite on a declared
        # object and not on prose.  ALL FOUR ARE MEASURED AND ALL ARE FALSE.
        "objects_registered": bool(REGISTERED_OBJECTS or ADOPTED_OBJECTS),
        "ward_contraction_claimed": WARD_CONTRACTION_CLAIMED,
        "gravity_claimed": GRAVITY_CLAIMED,
        "complex_gauge_equivalence_claimed": COMPLEX_GAUGE_EQUIVALENCE_CLAIMED,
    }
    return Facts(
        main_head=main_head,
        authority=authority_certificate(main_head),
        note_at_final_path=at_final_path,
        scope=scope_certificate(text),
        banners=banners,
        correction_pins=correction_pins,
        isometry_residual=isometry_residual,
        patch_dim=A.shape[0],
        range_invariance_residual=range_invariance_residual,
        hodge_pullback_residual=hodge_pullback_residual,
        action_pullback_residual=action_pullback_residual,
        mass_is_symbolic=bool(SYMBOLIC_MASS.is_Symbol
                              and SYMBOLIC_MASS.is_positive
                              and SYMBOLIC_MASS in Q_patch.free_symbols
                              and SYMBOLIC_MASS in Q_s_symbolic.free_symbols),
        cover_grading_residual=cover_grading_residual,
        quotient_grading_residual=quotient_grading_residual,
        quotient_grade_is_b106_verbatim=quotient_grade_is_b106_verbatim,
        canonical_defect_rank=canonical_defect_rank,
        transported_defect_rank=transported_defect_rank,
        grade_intertwiner_residual=grade_intertwiner_residual,
        anticommutator_residual=anticommutator_residual,
        square_residual=square_residual,
        squares_are_not_identity=squares_are_not_identity,
        two_step_flat_residual=two_step_flat_residual,
        one_step_commutator_rank=one_step_commutator_rank,
        signed_conjugate_nilpotency_residual=(
            signed_conjugate_nilpotency_residual),
        signed_conjugate_rank=signed_conjugate_rank,
        signed_conjugate_identity_residual=signed_conjugate_identity_residual,
        signed_conjugate_is_d10=signed_conjugate_is_d10,
        signed_conjugate_is_graded=signed_conjugate_is_graded,
        hodge_control_residual=hodge_control_residual,
        plain_covariance_residual=plain_covariance_residual,
        flip_residual=flip_residual,
        unflipped_residual_rank=unflipped_residual_rank,
        flipped_residual_rank=flipped_residual_rank,
        quotient_descent_residual=quotient_descent_residual,
        two_step_curved_residual=two_step_curved_residual,
        fine_periodic_rank=fine_periodic_rank,
        quotient_antiperiodic_rank=quotient_antiperiodic_rank,
        harmonic_modes=harmonic_modes,
        complex_difference_entries=complex_difference_entries,
        complex_seam_entries=complex_seam_entries,
        quotient_is_seam_negation=quotient_is_seam_negation,
    )


# ---------------------------------------------------------------------------
# the gates: pure functions of the measured facts and the claims
# ---------------------------------------------------------------------------
def build_checks(facts: Facts, claims: dict) -> Checks:
    checks = Checks()
    authority = facts.authority
    parent_blobs_ok = (authority.parent_artifact_blobs
                       if claims["parent_pin"] == "resolved"
                       else authority.stale_parent_artifact_blobs)

    # --- A: authority -------------------------------------------------------
    checks.check(
        "A-authority-and-THE-STALE-PIN-THAT-PREDATES-BOTH-ARTIFACTS",
        "THE FIVE-PIN AUTHORITY BLOCK binds origin/main's head, the axioms "
        "blob and the registry blob at origin/main, and the axioms and "
        "registry blobs in the worktree. THE TWO BLOCK 181 ARTIFACTS ARE "
        "CONTENT-BOUND -- its note and its runner, the pair that identifies "
        "the commit this block's branch is cut from -- at PARENT_COMMIT, in "
        "the worktree and against their pinned blobs, and PARENT_COMMIT IS "
        "REAL and PARENT_REF resolves to it, so nothing needs sed at landing. "
        "THE STALE PIN IS THE BLOCK 180 TIP, a REAL ancestor of HEAD that "
        "PREDATES Block 181 and therefore carries NEITHER Block 181 artifact, "
        "which is exactly what makes the stale_parent_authority mutation bite: "
        "under it the gate looks for the artifact blobs at a commit where they "
        "do not exist. AUDIT_INPUT_PATHS IS LITERAL and every one of its eight "
        "entries is required readable in the worktree EXCEPT this block's own "
        "note, which lands later and belongs to gate H. AND BOTH MACHINERY "
        "IMPORTS ARE GATED: the LANDED Block 128 runner AND the LANDED Block "
        "106 runner must both have imported, because every object this runner "
        "measures is rebuilt from them and from the Block 105 module Block 128 "
        "re-exports -- NOTHING from any scratchpad is imported or read anywhere",
        bool(
            AUDIT_INPUT_PATHS[0] == SELF_NOTE_INPUT
            and len(AUDIT_INPUT_PATHS) == 8
            and len(set(AUDIT_INPUT_PATHS)) == 8
            and BLOCK181_NOTE in AUDIT_INPUT_PATHS
            and BLOCK181_RUNNER in AUDIT_INPUT_PATHS
            and BLOCK128_NOTE in AUDIT_INPUT_PATHS
            and BLOCK128_RUNNER in AUDIT_INPUT_PATHS
            and BLOCK106_NOTE in AUDIT_INPUT_PATHS
            and BLOCK106_RUNNER in AUDIT_INPUT_PATHS
            and CAMPAIGN_NOTE in AUDIT_INPUT_PATHS
            # EVERY AUDIT INPUT BUT THIS BLOCK'S OWN NOTE IS READABLE IN THE
            # WORKTREE; the note itself is gate H's, because it lands later.
            and authority.inputs_readable == len(AUDIT_INPUT_PATHS) - 1
            and authority.inputs_missing == ()
            and PARENT_ARTIFACTS == (BLOCK181_NOTE, BLOCK181_RUNNER)
            and len(PARENT_ARTIFACT_BLOBS) == len(PARENT_ARTIFACTS) == 2
            and facts.main_head == claims["main_head"]
            and authority.fixed_authority
            and authority.machinery_import_landed
            and authority.parent_pin_is_commit
            and authority.parent_ref_and_ancestry
            and parent_blobs_ok
            # THE STALE PIN: a REAL ancestor of HEAD that carries NEITHER
            # Block 181 artifact.
            and authority.stale_is_real_ancestor
            and authority.stale_carries_neither_artifact))

    # --- B: the imposed-object banner and the NOT-CLAIMED keys -------------
    ban = facts.banners
    checks.check(
        "B-THE-IMPOSED-OBJECT-BANNER-and-the-NOT-CLAIMED-keys",
        f"THE BANNER COMES BEFORE ANY NUMERAL AND IT IS MEASURED RATHER THAN "
        f"ASSERTED. {ban['imposed_objects']} objects are IMPOSED by this block "
        f"-- the certified Block 105 curved carrier as landed by Block 128 and "
        f"re-used by Block 181, the four chart origins with their plain cover "
        f"shifts, the redundant four-patch carrier with the halved graph "
        f"section A = s/2 and its patch differential and replicated patch "
        f"Hodge, the Block 106 exterior grade with its canonical and "
        f"co-transported patch versions, the signed lifts with their sign "
        f"field, and the parameterized cover Hodge with the landed curved "
        f"Hodge as its control -- and {ban['registered_objects']} are "
        f"REGISTERED and {ban['adopted_objects']} are ADOPTED. AND THE "
        f"BANNER'S SECOND HALF IS WHAT IS NOT CLAIMED, gated as declared "
        f"constants: NO OS OR WARD-CONTRACTION THEOREM IS CLAIMED, because the "
        f"same-action pullback reproduces the graded Ward ACTION on range(A) "
        f"and nothing more -- Block 106's own disclaimer, carried verbatim; NO "
        f"GRAVITY RESULT IS CLAIMED, because the shear flip is KINEMATIC frame "
        f"data and no ADM temporal link is derived here; and NO GAUGE "
        f"EQUIVALENCE OF THE TWO 16-DIMENSIONAL COMPLEXES IS CLAIMED, because "
        f"they are COMPARED and never identified. Asserting any of the three, "
        f"or asserting that the imposed objects are registered, fails HERE and "
        f"nowhere else",
        bool(
            ban["imposed_objects"] == 6
            and ban["registered_objects"] == 0
            and ban["adopted_objects"] == 0
            and ban["objects_registered"] == claims["objects_registered"]
            and ban["ward_contraction_claimed"]
            == claims["ward_contraction_claimed"]
            and ban["gravity_claimed"] == claims["gravity_claimed"]
            and ban["complex_gauge_equivalence_claimed"]
            == claims["complex_gauge_equivalence_claimed"]))

    # --- C: the corpus-correction certificate ------------------------------
    pins = facts.correction_pins
    checks.check(
        "C-THE-CORPUS-CORRECTION-certificate-read-from-the-PRIMARY-BODIES",
        f"THE CORRECTION IS GROUNDED IN MEASURED TEXT, NOT IN MEMORY. The "
        f"2026-08-15 note IS BLOCK 106, and its OWN PRIMARY BODY carries both "
        f"pins: its section 1 sentence '{B106_EXECUTED_PIN}' is present "
        f"{pins['b106_executed_pin']}, and its front-matter line "
        f"'{B106_REACHABILITY_PIN}' is present {pins['b106_reachability_pin']} "
        f"-- so Block 106 EXECUTED the 2026-08-15 blocker AT ITS OWN SCOPE on "
        f"the date it landed. THE BLOCK 181 NOTE'S PHRASE IS PINNED PRESENT "
        f"TOO ({pins['b181_stale_pin']}), because a correction with no "
        f"measured referent is an assertion: that note records the dual-patch "
        f"pullback clauses as ones that 'stay OPEN', which is WRONG AT CORPUS "
        f"SCOPE and right only as 'not executed on the b128 curved carrier'. "
        f"AND BLOCK 106's OWN LIMIT IS PINNED WITH IT "
        f"({pins['b106_no_ward_pin']}): its same-action row reads 'not a "
        f"spectral analogy or a Ward-contraction theorem', which is the "
        f"disclaimer gate B carries forward. THE CORRECTION EDITS NO LANDED "
        f"NOTE ({not pins['correction_edits_a_landed_note']}) -- it is a "
        f"CITATION correction shipped as this block's content, and every Block "
        f"106 and Block 181 number stands exactly as landed. Denying the "
        f"Block 106 execution pin fails HERE and nowhere else",
        bool(
            pins["b106_executed_pin"] == claims["b106_executed_pin"]
            and pins["b106_reachability_pin"] == claims["b106_reachability_pin"]
            and pins["b106_no_ward_pin"] == claims["b106_no_ward_pin"]
            and pins["b181_stale_pin"] == claims["b181_stale_pin"]
            and pins["correction_edits_a_landed_note"]
            == claims["correction_edits_a_landed_note"]))

    # --- D: the isometry package, T1 ---------------------------------------
    checks.check(
        "D-T1-the-halved-graph-section-is-an-EXACT-ISOMETRY",
        f"A = s/2, the LANDED Block 181 graph section over two, maps the "
        f"32-dimensional cover into the {facts.patch_dim}-dimensional "
        f"redundant patch carrier V^+4 with A^T A = I EXACTLY -- the Block 106 "
        f"eq-12 four-fold-cover identity, on this carrier. NO OPERATOR INVERSE "
        f"APPEARS ANYWHERE",
        facts.isometry_residual == claims["isometry_residual"]
        and facts.patch_dim == claims["patch_dim"])
    checks.check(
        "D-T1-range-invariance-D_patch-A-equals-A-d00-eq-18",
        "D_patch A = A d_00 with a ZERO residual: the physical range of the "
        "section is D-INVARIANT, which is the Block 106 equation (18) "
        "range-invariance form transplanted onto the curved section frame",
        facts.range_invariance_residual
        == claims["range_invariance_residual"])
    checks.check(
        "D-T1-Hodge-pullback-A-H_patch-A-equals-H_s-eq-24",
        "A^T H_patch A = H_s with a ZERO residual, where H_patch is the LANDED "
        "curved Hodge REPLICATED per patch: THE BLOCK 181 SECTION HODGE IS THE "
        "ANALYSIS PULLBACK OF THE PATCH HODGE, which is Block 106 equation "
        "(24) on this carrier -- the orbit average was never an ad-hoc choice",
        facts.hodge_pullback_residual == claims["hodge_pullback_residual"])
    checks.check(
        "D-T1-SAME-ACTION-pullback-A-Q_patch-A-equals-Q_s-eq-26-SYMBOLIC-MASS",
        f"A^T Q_patch A = Q_s with a ZERO residual AT SYMBOLIC POSITIVE MASS "
        f"({facts.mass_is_symbolic}: the mass is a free positive Symbol and it "
        f"is present in both actions, so the identity is an operator identity "
        f"in m and not a coincidence at MASS = 2/7). THIS IS THE SAME-ACTION "
        f"PULLBACK, Block 106 equation (26): the patch action with replicated "
        f"onsite geometry induces EXACTLY the section-frame action on the "
        f"physical carrier, with zero contact terms. The graded Ward action is "
        f"reproduced on range(A) in Block 106's own sense and NO "
        f"WARD-CONTRACTION THEOREM IS CLAIMED",
        facts.action_pullback_residual == claims["action_pullback_residual"]
        and facts.mass_is_symbolic == claims["mass_is_symbolic"])

    # --- E: the grading, T2 -------------------------------------------------
    checks.check(
        "E-T2-cover-grading-[N,d00]=d00-with-BLOCK-106s-OWN-DEGREE",
        "[N, d_00] = d_00 EXACTLY on the 32-dimensional cover, with the "
        "exterior degree deg = t%2 + x%2 -- Block 106's own census, not a "
        "degree invented here. The chart differential is grade-raising by one "
        "against a degree that was fixed two blocks upstream",
        facts.cover_grading_residual == claims["cover_grading_residual"])
    checks.check(
        "E-T2-quotient-grading-and-N_q-EQUALS-BLOCK-106s-N_glob-VERBATIM",
        f"[N_q, d_q] = d_q EXACTLY on the 16-dimensional antiperiodic "
        f"quotient, and N_q IS BLOCK 106's N_glob VERBATIM as a matrix "
        f"({facts.quotient_grade_is_b106_verbatim}) -- read from the LANDED "
        f"Block 106 module and compared entry for entry, not re-derived and "
        f"declared equal. THE TWO CARRIERS SHARE THEIR GRADING EXACTLY, which "
        f"is what makes the R-versus-NS comparison in gate G a comparison and "
        f"not a category error",
        facts.quotient_grading_residual == claims["quotient_grading_residual"]
        and facts.quotient_grade_is_b106_verbatim
        == claims["quotient_grade_is_b106_verbatim"])
    checks.check(
        "E-T2-CANONICAL-patch-grade-defect-is-EXACT-rank-48-the-W1-analogue",
        f"the CANONICAL untransported patch grade diag(N,N,N,N) is NOT a grade "
        f"operator for D_patch: its commutator defect has EXACT RANK "
        f"{facts.canonical_defect_rank} on the 128-dimensional patch carrier. "
        f"THIS IS THE BLOCK 106 W1 ANALOGUE, whose defect was rank "
        f"{B106_CANONICAL_GRADE_DEFECT_RANK} on its 64-dimensional carrier -- "
        f"the same wall, re-measured on the curved section frame. Asserting "
        f"the canonical grade compatible fails HERE and nowhere else",
        facts.canonical_defect_rank == claims["canonical_defect_rank"])
    checks.check(
        "E-T2-CO-TRANSPORTED-grade-closes-the-defect-to-EXACTLY-ZERO",
        f"the CO-TRANSPORTED grade N_patch = diag(S_o N S_o^T) has commutator "
        f"defect of rank {facts.transported_defect_rank} -- EXACTLY ZERO -- and "
        f"satisfies N_patch A = A N with a ZERO residual. THE GRADE "
        f"CO-TRANSFORMS WITH THE FRAME, exactly as Block 106's N_ext did "
        f"against its own canonical census: the Block 106 lesson replicated, "
        f"not re-derived from scratch",
        facts.transported_defect_rank == claims["transported_defect_rank"]
        and facts.grade_intertwiner_residual
        == claims["grade_intertwiner_residual"])

    # --- F: the signed lifts and the symmetry, S3a / S5 / T3 ---------------
    checks.check(
        "F-S3a-EXACT-projective-algebra-of-the-signed-lifts-eq-29",
        f"Ut~ = diag((-1)^x) U_t and Ux~ = U_x ANTICOMMUTE EXACTLY, and their "
        f"squares are the PLAIN two-step translations "
        f"{tuple(facts.square_residual.values())} at zero residual -- which "
        f"are NOT the identity ({facts.squares_are_not_identity}), so the "
        f"algebra is genuinely projective and not a relabelled abelian one. "
        f"This is Block 106 equation (29) on the curved cover. Asserting a "
        f"nonzero anticommutator residual fails HERE and nowhere else",
        facts.anticommutator_residual == claims["anticommutator_residual"]
        and all(value == claims["square_residual"]
                for value in facts.square_residual.values())
        and facts.squares_are_not_identity
        == claims["squares_are_not_identity"])
    checks.check(
        "F-S5-the-TWO-STEP-shifts-are-the-honest-flat-symmetries",
        f"[U_t^2, Q(I, d_00)] = 0 and [U_x^2, Q(I, d_00)] = 0 EXACTLY against "
        f"the flat completion "
        f"{tuple(facts.two_step_flat_residual.values())}: the two-step shifts "
        f"commute with the flat completion outright, on both axes",
        all(value == claims["two_step_flat_residual"]
            for value in facts.two_step_flat_residual.values()))
    checks.check(
        "F-S5-the-PLAIN-ONE-STEP-shift-MOVES-THE-CHART-at-EXACT-rank-24",
        f"the plain ONE-STEP time shift has commutator rank "
        f"{facts.one_step_commutator_rank} against the SAME flat completion. "
        f"ONE-STEP SHIFTS MOVE THE CHART, and the number is measured in the "
        f"same run as the two-step zeros so the contrast is like-for-like: the "
        f"honest symmetry group of the chart-fixed completion is the two-step "
        f"lattice and not the one-step one. Asserting the one-step shift a "
        f"symmetry fails HERE and nowhere else",
        facts.one_step_commutator_rank == claims["one_step_commutator_rank"])
    checks.check(
        "F-T3-the-SIGNED-CONJUGATE-classified-a-HODGE-PARITY-carrier",
        f"Ut~ d_00 Ut~^T is NILPOTENT with a zero square and rank "
        f"{facts.signed_conjugate_rank}, and it equals sgn_x d_10 sgn_x "
        f"EXACTLY at zero residual. IT IS NOT d_10 "
        f"({not facts.signed_conjugate_is_d10}) AND IT IS NOT N-GRADED "
        f"({not facts.signed_conjugate_is_graded}). THE SIGNED LIFT IS A "
        f"HODGE-PARITY CARRIER AND NOT A CHART TRANSITION: the chart family "
        f"and the sign-dressed family are DISTINCT ORBITS, and the classifying "
        f"identity is exhibited rather than asserted",
        facts.signed_conjugate_nilpotency_residual
        == claims["signed_conjugate_nilpotency_residual"]
        and facts.signed_conjugate_rank == claims["signed_conjugate_rank"]
        and facts.signed_conjugate_identity_residual
        == claims["signed_conjugate_identity_residual"]
        and facts.signed_conjugate_is_d10 == claims["signed_conjugate_is_d10"]
        and facts.signed_conjugate_is_graded
        == claims["signed_conjugate_is_graded"])

    # --- G: the shear-flip package and the R-versus-NS dividend ------------
    checks.check(
        "G-S4-CONTROL-the-parameterized-Hodge-reproduces-the-LANDED-one",
        "H[landed field] equals the LANDED b128 curved_hodge_cover() EXACTLY, "
        "at zero residual. THE CONTROL COMES FIRST: every covariance statement "
        "below is about a family whose base point is the landed object itself, "
        "so no covariance is bought by redefining the Hodge",
        facts.hodge_control_residual == claims["hodge_control_residual"])
    checks.check(
        "G-S4-PLAIN-shifts-move-the-field-exactly-on-both-axes-both-directions",
        f"the plain shifts satisfy U H[g] U^T = H[T g] with a ZERO residual in "
        f"all four cases {tuple(facts.plain_covariance_residual.values())} -- "
        f"forward and backward, temporal and spatial. This is Block 106 "
        f"equation (32) on the curved cover",
        all(value == claims["plain_covariance_residual"]
            for value in facts.plain_covariance_residual.values()))
    checks.check(
        "G-S4-THE-SIGNED-t-FLIP-IDENTITY-IS-EXACT-eq-34",
        "Ut~ H[g] Ut~^T = H[T_t F g] with F(q,v) = (-q,v) at a ZERO residual: "
        "THE REFLECTION-ODD ADM SHEAR PARITY IS EXACT ON THE CURVED SECTION "
        "FRAME. This is Block 106 equation (34), and the shear flip is the "
        "thing the temporal transporter must carry. Asserting a nonzero flip "
        "residual fails HERE and nowhere else",
        facts.flip_residual == claims["flip_residual"])
    checks.check(
        "G-S4-BOTH-WRONG-PAIRINGS-FAIL-AT-FULL-RANK-32",
        f"the signed-t lift against the UNFLIPPED translate fails at rank "
        f"{facts.unflipped_residual_rank}, and the PLAIN t lift against the "
        f"FLIPPED translate fails at rank {facts.flipped_residual_rank} -- "
        f"BOTH FULL RANK on the 32-dimensional cover. Block 106's analogue "
        f"residual was rank {B106_UNFLIPPED_RESIDUAL_RANK} on its "
        f"block-diagonal patch carrier, where two flat anchors left it "
        f"deficient; on this OVERLAPPING cover the failure SATURATES. The flip "
        f"is not a convention that could be absorbed",
        facts.unflipped_residual_rank == claims["unflipped_residual_rank"]
        and facts.flipped_residual_rank == claims["flipped_residual_rank"])
    checks.check(
        "G-T4-THE-PARITY-DESCENDS-THROUGH-THE-ANTIPERIODIC-QUOTIENT",
        f"on the 16-dimensional antiperiodic quotient all three descents are "
        f"EXACT at zero residual "
        f"{tuple(facts.quotient_descent_residual.values())}: plain-x "
        f"conjugation descends untwisted, the TWISTED-t (antiperiodic-wrapped) "
        f"shift gives PLAIN-FIELD covariance, and the SIGNED-twisted-t shift "
        f"gives FLIPPED-FIELD covariance. THE REFLECTION-ODD ADM PARITY LIVES "
        f"ON THE PHYSICAL CARRIER AND NOT ONLY ON THE COVER -- this is the "
        f"seam structure the ADM/history gate needs, and deriving the link "
        f"from it is NOT done here",
        all(value == claims["quotient_descent_residual"]
            for value in facts.quotient_descent_residual.values()))
    checks.check(
        "G-S5-EXACT-two-step-FIELD-MOVED-covariance-of-the-CURVED-completion",
        f"U^2 Q_s[g] U^2T = Q_s[T^2 g] at a ZERO residual in all four cases "
        f"{tuple(facts.two_step_curved_residual.values())}, with Q_s[f] built "
        f"from the orbit-averaged H_s[f] against the FIXED d_00: the curved "
        f"section completion carries the two-step symmetry as a FIELD-MOVED "
        f"covariance, on both axes and in both directions",
        all(value == claims["two_step_curved_residual"]
            for value in facts.two_step_curved_residual.values()))
    checks.check(
        "G-THE-R-VERSUS-NS-DIVIDEND-rank-6-against-rank-8-NOT-IDENTIFIED",
        f"the LANDED Block 106 PERIODIC fine differential has EXACT RANK "
        f"{facts.fine_periodic_rank}, leaving {facts.harmonic_modes} harmonic "
        f"modes -- the torus Betti numbers 1+2+1 -- while the LANDED Block 181 "
        f"ANTIPERIODIC quotient differential has EXACT RANK "
        f"{facts.quotient_antiperiodic_rank} and is ACYCLIC. THE TWIST KILLS "
        f"EXACTLY THE HARMONIC SECTOR. AND THE TWO ARE NOT THE SAME OPERATOR: "
        f"their difference has EXACTLY {facts.complex_difference_entries} "
        f"nonzero entries of which EXACTLY {facts.complex_seam_entries} sit on "
        f"the t-seam, and the quotient differential is NOT the seam-negation "
        f"of the fine one ({not facts.quotient_is_seam_negation}). SAME "
        f"GRADING, DIFFERENT OPERATORS, NO GAUGE EQUIVALENCE CLAIMED. "
        f"Asserting the periodic rank equal to the antiperiodic one fails HERE "
        f"and nowhere else",
        facts.fine_periodic_rank == claims["fine_periodic_rank"]
        and facts.quotient_antiperiodic_rank
        == claims["quotient_antiperiodic_rank"]
        and facts.harmonic_modes == HARMONIC_MODES
        and facts.complex_difference_entries
        == claims["complex_difference_entries"]
        and facts.complex_seam_entries == claims["complex_seam_entries"]
        and facts.quotient_is_seam_negation
        == claims["quotient_is_seam_negation"])

    # --- H: the note at its final path, and the N5 fence -------------------
    required = tuple(claims["required_scope_keys"])
    checks.check(
        "H-note-at-final-path-and-the-N5-fence",
        f"the note is read at its FINAL PATH {facts.note_at_final_path} -- "
        f"THERE IS NO DRAFT FALLBACK ANYWHERE IN THIS RUNNER, so when False "
        f"the note has not landed at docs/ yet, gate H is EXPECTED to fail on "
        f"that alone, and families A through G are unaffected. The N5 fence is "
        f"an N5-prefixed single-line literal with nine labelled sections that "
        f"must appear BYTE-IDENTICALLY in the note, the required scope-key set "
        f"is THE FULL DECLARED SET and not a subset, and the mutation battery "
        f"is fifteen members mapped one-per-family across A through H",
        bool(
            facts.note_at_final_path
            and NOTE_PATH.name == FINAL_NOTE_NAME
            and set(facts.scope) == set(SCOPE_KEYS)
            # THE FULL KEY SET IS REQUIRED, not a subset.
            and required == SCOPE_KEYS
            and all(facts.scope[key] for key in required)
            and facts.scope["n5_verbatim"]
            and len(MUTATIONS) == 15
            and len(set(MUTATIONS)) == 15
            and set(MUTATION_GATE) == set(MUTATIONS)
            and set(MUTATION_GATE.values()) == set("ABCDEFGH")
            and N5_FENCE.startswith("N5: ")
            and 9 <= N5_FENCE.count("\n") + 1 <= 12
            and all(N5_FENCE.count(f"\n{name}:") == 1
                    for name in ("per_site", "per_mode", "per_block",
                                 "lattice_wide", "per_scope", "RESULT",
                                 "DECISION_CUT", "TOE"))))
    return checks


